<script setup lang="ts">
import {nextTick,onBeforeUnmount,onMounted,ref} from 'vue'
const p=defineProps<{title:string;busy?:boolean}>();const emit=defineEmits<{close:[]}>();const dialog=ref<HTMLElement|null>(null);let previous:HTMLElement|null=null
onMounted(async()=>{previous=document.activeElement as HTMLElement;await nextTick();dialog.value?.focus()});onBeforeUnmount(()=>{if(previous?.isConnected)previous.focus()})
function keys(e:KeyboardEvent){if(e.key==='Escape'&&!p.busy){e.preventDefault();emit('close')}if(e.key!=='Tab')return;const a=Array.from(dialog.value?.querySelectorAll<HTMLElement>('button:not(:disabled),a[href],input:not(:disabled),select:not(:disabled),textarea:not(:disabled),[tabindex="0"]')||[]).filter(v=>v.getClientRects().length);if(!a.length){e.preventDefault();return}const first=a[0],last=a[a.length-1];if(e.shiftKey&&(document.activeElement===first||document.activeElement===dialog.value)){e.preventDefault();last?.focus()}else if(!e.shiftKey&&(document.activeElement===last||document.activeElement===dialog.value)){e.preventDefault();first?.focus()}}
</script><template><Teleport to="body"><div class="sb-overlay" @click.self="!busy&&emit('close')"><section ref="dialog" tabindex="-1" class="sb-dialog sales-business" role="dialog" aria-modal="true" :aria-label="title" @keydown="keys"><header class="sb-toolbar"><h2>{{title}}</h2><button type="button" :disabled="busy" @click="emit('close')">关闭</button></header><slot/></section></div></Teleport></template>
